"""
avatar/avatar_controller.py
Loads a Mixamo GLB character with idle/talking/nod animations.
Switches animations based on conversation state via WebSocket.
Drives jaw bone lip-sync from live Web Audio analyser.
Serves models via HTTP to avoid CORS issues.
"""
import asyncio, os, tempfile, webbrowser, json, threading, socket
from pathlib import Path
import websockets
from websockets.exceptions import ConnectionClosed
from http.server import HTTPServer, SimpleHTTPRequestHandler

connected_clients: set = set()

async def broadcast(message: dict) -> None:
    if not connected_clients:
        return
    data = json.dumps(message)
    await asyncio.gather(
        *[_safe_send(ws, data) for ws in list(connected_clients)],
        return_exceptions=True,
    )

async def _safe_send(ws, data: str) -> None:
    try:
        await ws.send(data)
    except ConnectionClosed:
        connected_clients.discard(ws)

async def _handler(websocket) -> None:
    connected_clients.add(websocket)
    try:
        async for _ in websocket:
            pass
    except ConnectionClosed:
        pass
    finally:
        connected_clients.discard(websocket)

def _start_http_server():
    """Start a simple HTTP server to serve model files with CORS."""
    models_dir = Path(__file__).parent / "models"
    
    class Handler(SimpleHTTPRequestHandler):
        def __init__(self, *args, **kwargs):
            self.models_dir = models_dir
            super().__init__(*args, directory=str(models_dir), **kwargs)
        
        def end_headers(self):
            self.send_header('Access-Control-Allow-Origin', '*')
            self.send_header('Access-Control-Allow-Methods', 'GET, OPTIONS')
            self.send_header('Access-Control-Allow-Headers', 'Content-Type')
            super().end_headers()
        
        def do_OPTIONS(self):
            self.send_response(200)
            self.end_headers()
        
        def log_message(self, format, *args):
            pass  # Suppress logging
    
    http_port = _find_free_port(7863)  # Use 7863 for HTTP, not 7862
    server = HTTPServer(("localhost", http_port), Handler)
    print(f"HTTP server started on http://localhost:{http_port} serving {models_dir}")
    thread = threading.Thread(target=server.serve_forever, daemon=True)
    thread.start()
    return http_port

def _find_free_port(start_port=7861):
    """Find a free port by trying ports sequentially."""
    for port in range(start_port, start_port + 20):
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
                s.bind(('127.0.0.1', port))
                return port
        except OSError:
            continue
    raise RuntimeError(f"No free ports found between {start_port} and {start_port + 19}")

async def start_server() -> None:
    from utils.config import WS_PORT
    
    # Start HTTP server for model files (returns the port it's using)
    http_port = _start_http_server()
    
    # Find a free port for WebSocket (handle TIME_WAIT state)
    ws_port = _find_free_port(WS_PORT)
    if ws_port != WS_PORT:
        print(f"Port {WS_PORT} unavailable, using {ws_port} instead")
    
    # Replace relative paths with HTTP URLs
    html = _HTML.replace("__WS_PORT__", str(ws_port))
    html = html.replace("avatar/models/", f"http://localhost:{http_port}/")
    
    tmp = tempfile.NamedTemporaryFile(mode="w", suffix=".html", delete=False, encoding="utf-8")
    tmp.write(html)
    tmp.close()
    webbrowser.open("file:///" + tmp.name.replace(os.sep, "/"))
    print(f"Avatar UI opened | WebSocket on ws://localhost:{ws_port}")
    
    async with websockets.serve(_handler, "127.0.0.1", ws_port):
        await asyncio.Future()


_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8"/>\n<title>AI Voice Assistant</title>\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{\n  width:100vw;height:100vh;overflow:hidden;\n  background:radial-gradient(ellipse at 25% 60%, #0a1628 0%, #050a14 55%, #000 100%);\n  font-family:"Segoe UI",system-ui,sans-serif;color:#e8eaf6;display:flex;\n}\n#stars{position:fixed;inset:0;z-index:0;pointer-events:none}\n#avatar-panel{\n  position:relative;z-index:1;width:63%;height:100vh;\n  display:flex;align-items:center;justify-content:center;overflow:hidden;\n}\n#three-canvas{display:block;width:100%!important;height:100%!important}\n#loader{\n  position:absolute;inset:0;z-index:10;\n  display:flex;flex-direction:column;align-items:center;justify-content:center;gap:18px;\n  background:rgba(5,10,20,.85);backdrop-filter:blur(8px);\n}\n#loader-ring{\n  width:52px;height:52px;border-radius:50%;\n  border:3px solid rgba(100,140,255,.2);border-top-color:#6488ff;\n  animation:spin 1s linear infinite;\n}\n@keyframes spin{to{transform:rotate(360deg)}}\n#loader p{font-size:.9rem;opacity:.7;letter-spacing:.05em}\n#loader-bar-wrap{width:220px;height:4px;background:rgba(255,255,255,.08);border-radius:2px;overflow:hidden}\n#loader-bar{height:100%;width:0%;background:linear-gradient(90deg,#4466ff,#9944ff);transition:width .3s;border-radius:2px}\n\n#chat-panel{\n  position:relative;z-index:1;width:37%;height:100vh;\n  display:flex;flex-direction:column;padding:24px 20px 20px;\n  background:rgba(255,255,255,.03);backdrop-filter:blur(24px);\n  border-left:1px solid rgba(255,255,255,.07);\n}\n#chat-panel h2{\n  font-size:1rem;font-weight:700;letter-spacing:.1em;color:rgba(160,180,255,.9);\n  text-transform:uppercase;margin-bottom:16px;padding-bottom:14px;\n  border-bottom:1px solid rgba(255,255,255,.07);\n  display:flex;align-items:center;gap:10px;\n}\n#chat-panel h2 span{font-size:1.3rem}\n#messages{\n  flex:1;overflow-y:auto;display:flex;flex-direction:column;gap:12px;padding-right:4px;\n  scrollbar-width:thin;scrollbar-color:rgba(255,255,255,.08) transparent;\n}\n#messages::-webkit-scrollbar{width:3px}\n#messages::-webkit-scrollbar-thumb{background:rgba(255,255,255,.1);border-radius:2px}\n.msg{padding:11px 15px;border-radius:14px;max-width:95%;font-size:.875rem;line-height:1.55;animation:up .25s ease}\n@keyframes up{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}\n.msg.user{align-self:flex-end;background:rgba(80,110,255,.22);border:1px solid rgba(80,110,255,.28);border-bottom-right-radius:3px}\n.msg.assistant{align-self:flex-start;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.09);border-bottom-left-radius:3px}\n.msg .who{display:block;font-size:.68rem;font-weight:700;letter-spacing:.07em;text-transform:uppercase;margin-bottom:4px;opacity:.65}\n.msg.user .who{color:#8899ff}\n.msg.assistant .who{color:#88ddb8}\n.msg p{margin:0}\n#status-bar{\n  margin-top:16px;padding-top:15px;border-top:1px solid rgba(255,255,255,.07);\n  display:flex;align-items:center;gap:10px;\n}\n#sdot{\n  width:9px;height:9px;border-radius:50%;background:#333;flex-shrink:0;transition:background .3s,box-shadow .3s;\n}\n#sdot.listening{background:#3dba5f;box-shadow:0 0 8px #3dba5f}\n#sdot.thinking {background:#3399ff;box-shadow:0 0 8px #3399ff;animation:blink 1s infinite}\n#sdot.speaking  {background:#aa44ee;box-shadow:0 0 8px #aa44ee;animation:blink .6s infinite}\n#sdot.disconnected{background:#555}\n@keyframes blink{0%,100%{opacity:1}50%{opacity:.35}}\n#stxt{font-size:.82rem;opacity:.75;letter-spacing:.03em}\n\n/* Waveform bars shown while speaking */\n#wave{display:flex;align-items:center;gap:3px;height:20px;margin-left:auto;opacity:0;transition:opacity .3s}\n#wave.active{opacity:1}\n#wave span{display:block;width:3px;border-radius:2px;background:#aa44ee;animation:none}\n#wave.active span:nth-child(1){animation:bar 0.9s ease infinite}\n#wave.active span:nth-child(2){animation:bar 0.9s ease .15s infinite}\n#wave.active span:nth-child(3){animation:bar 0.9s ease .3s  infinite}\n#wave.active span:nth-child(4){animation:bar 0.9s ease .45s infinite}\n#wave.active span:nth-child(5){animation:bar 0.9s ease .6s  infinite}\n@keyframes bar{0%,100%{height:4px}50%{height:18px}}\n</style>\n</head>\n<body>\n<canvas id="stars"></canvas>\n\n<div id="avatar-panel">\n  <canvas id="three-canvas"></canvas>\n  <div id="loader">\n    <div id="loader-ring"></div>\n    <div id="loader-bar-wrap"><div id="loader-bar"></div></div>\n    <p id="loader-msg">Loading character...</p>\n  </div>\n</div>\n\n<div id="chat-panel">\n  <h2><span>&#x1F916;</span> Voice Assistant</h2>\n  <div id="messages">\n    <div class="msg assistant">\n      <span class="who">Assistant</span>\n      <p>Hi! Press <strong>Enter</strong> in the terminal to start speaking.</p>\n    </div>\n  </div>\n  <div id="status-bar">\n    <div id="sdot"></div>\n    <span id="stxt">Connecting...</span>\n    <div id="wave">\n      <span></span><span></span><span></span><span></span><span></span>\n    </div>\n  </div>\n</div>\n\n<script type="importmap">\n{\n  "imports": {\n    "three": "https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js",\n    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.160.0/examples/jsm/"\n  }\n}\n</script>\n\n<script type="module">\nimport * as THREE from "three";\nimport { GLTFLoader }       from "three/addons/loaders/GLTFLoader.js";\nimport { RGBELoader }       from "three/addons/loaders/RGBELoader.js";\nimport { OrbitControls }    from "three/addons/controls/OrbitControls.js";\n\nconst WS_URL = "ws://localhost:__WS_PORT__";\n\n// ── Renderer ──────────────────────────────────────────────────────────────\nconst canvas   = document.getElementById("three-canvas");\nconst panel    = document.getElementById("avatar-panel");\nconst renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });\nrenderer.setPixelRatio(Math.min(devicePixelRatio, 2));\nrenderer.shadowMap.enabled = true;\nrenderer.shadowMap.type    = THREE.PCFSoftShadowMap;\nrenderer.toneMapping       = THREE.ACESFilmicToneMapping;\nrenderer.toneMappingExposure = 1.15;\nrenderer.outputColorSpace  = THREE.SRGBColorSpace;\n\nconst scene  = new THREE.Scene();\n\nconst W = () => panel.clientWidth;\nconst H = () => innerHeight;\nconst camera = new THREE.PerspectiveCamera(38, W() / H(), 0.01, 50);\n// Framed for full body - adjust Y/Z to taste\ncamera.position.set(0, 0.95, 2.6);\ncamera.lookAt(0, 0.85, 0);\n\nconst controls = new OrbitControls(camera, canvas);\ncontrols.target.set(0, 0.85, 0);\ncontrols.enableDamping = true;\ncontrols.dampingFactor = 0.08;\ncontrols.minDistance   = 1.0;\ncontrols.maxDistance   = 5.0;\ncontrols.maxPolarAngle = Math.PI * 0.75;\ncontrols.update();\n\nfunction resize() {\n  renderer.setSize(W(), H());\n  camera.aspect = W() / H();\n  camera.updateProjectionMatrix();\n}\nresize();\naddEventListener("resize", resize);\n\n// ── Lighting ──────────────────────────────────────────────────────────────\nscene.add(new THREE.AmbientLight(0x445566, 1.6));\n\nconst sun = new THREE.DirectionalLight(0xfff4e0, 3.5);\nsun.position.set(2, 5, 3);\nsun.castShadow = true;\nsun.shadow.mapSize.set(2048, 2048);\nsun.shadow.camera.near = 0.1;\nsun.shadow.camera.far  = 20;\nsun.shadow.camera.left = sun.shadow.camera.bottom = -3;\nsun.shadow.camera.right = sun.shadow.camera.top = 3;\nsun.shadow.bias = -0.001;\nscene.add(sun);\n\nconst fillL = new THREE.DirectionalLight(0x4466bb, 1.4);\nfillL.position.set(-3, 2, 1);\nscene.add(fillL);\n\nconst rimL = new THREE.DirectionalLight(0x9933cc, 1.8);\nrimL.position.set(0, 4, -4);\nscene.add(rimL);\n\nconst underL = new THREE.PointLight(0x223355, 1.2, 6);\nunderL.position.set(0, -1, 1);\nscene.add(underL);\n\n// ── Floor ─────────────────────────────────────────────────────────────────\nconst floorG = new THREE.CircleGeometry(3, 64);\nconst floorM = new THREE.MeshStandardMaterial({\n  color: 0x0a0f1e, roughness: 0.9, metalness: 0.1\n});\nconst floor = new THREE.Mesh(floorG, floorM);\nfloor.rotation.x = -Math.PI / 2;\nfloor.receiveShadow = true;\nscene.add(floor);\n\n// Glow ring on floor\nconst ringG = new THREE.TorusGeometry(0.85, 0.012, 8, 64);\nconst ringM = new THREE.MeshBasicMaterial({ color: 0x5577ff, transparent: true, opacity: 0.5 });\nconst ring  = new THREE.Mesh(ringG, ringM);\nring.rotation.x = -Math.PI / 2;\nring.position.y = 0.001;\nscene.add(ring);\n\n// ── State ─────────────────────────────────────────────────────────────────\nlet mixer      = null;\nlet character  = null;\nlet jawBone    = null;\nlet morphMeshes = [];\n\nlet actionIdle    = null;\nlet actionTalking = null;\nlet actionNod     = null;\nlet currentAction = null;\n\nlet isSpeaking = false;\nlet currentJaw = 0;\n\n// ── Load character + animations ───────────────────────────────────────────\nconst loader   = new GLTFLoader();\nlet loadedCount = 0;\nconst totalLoads = 4;\n\nfunction onProgress(pct) {\n  loadedCount = Math.max(loadedCount, 0);\n  document.getElementById("loader-bar").style.width = pct + "%";\n}\n\nfunction modelLoadProgress(xhr) {\n  if (xhr.total) onProgress(Math.round(xhr.loaded / xhr.total * 80));\n}\n\nfunction hideLoader() {\n  document.getElementById("loader").style.display = "none";\n}\n\n// 1. Load character (body + skeleton)\nloader.load(\n  "avatar/models/character.glb",\n  gltf => {\n    character = gltf.scene;\n    character.traverse(node => {\n      if (!node.isMesh) return;\n      node.castShadow    = true;\n      node.receiveShadow = true;\n      node.frustumCulled = false;\n      if (node.morphTargetInfluences && node.morphTargetDictionary) {\n        morphMeshes.push(node);\n      }\n      // Improve material quality\n      if (node.material) {\n        const mats = Array.isArray(node.material) ? node.material : [node.material];\n        mats.forEach(m => {\n          m.envMapIntensity = 0.6;\n          if (m.map) m.map.anisotropy = renderer.capabilities.getMaxAnisotropy();\n        });\n      }\n    });\n\n    // Find jaw bone - Mixamo names it "mixamorigJaw" or similar\n    character.traverse(node => {\n      const n = node.name.toLowerCase();\n      if (n.includes("jaw") && !jawBone) {\n        jawBone = node;\n        console.log("Jaw bone found:", node.name);\n      }\n    });\n\n    scene.add(character);\n    mixer = new THREE.AnimationMixer(character);\n\n    // Load built-in animations if any\n    if (gltf.animations && gltf.animations.length > 0) {\n      gltf.animations.forEach(clip => {\n        const a = mixer.clipAction(clip);\n        if (!actionIdle) { actionIdle = a; actionIdle.play(); currentAction = actionIdle; }\n      });\n    }\n\n    document.getElementById("loader-msg").textContent = "Loading animations...";\n    onProgress(30);\n    loadAnimations();\n  },\n  modelLoadProgress,\n  err => {\n    document.getElementById("loader-msg").textContent =\n      "ERROR: Could not load character.glb — check avatar/models/";\n    console.error(err);\n  }\n);\n\nfunction fixClip(clip) {\n  const tracks = clip.tracks.map(t => {\n    const fixed = t.clone();\n    fixed.name = fixed.name.replace(/^.+\\|/, "");\n    return fixed;\n  });\n  return new THREE.AnimationClip(clip.name, clip.duration, tracks);\n}\n\nfunction loadAnimations() {\n  let done = 0;\n\n  function tryDone() {\n    done++;\n    onProgress(30 + done * 22);\n    if (done === 3) {\n      if (actionIdle) { actionIdle.play(); currentAction = actionIdle; }\n      hideLoader();\n      setStatus("listening");\n    }\n  }\n\n  // Idle animation\n  loader.load("avatar/models/idle.glb",\n    gltf => {\n      if (gltf.animations.length > 0) {\n        const clip = fixClip(gltf.animations[0]);\n        actionIdle = mixer.clipAction(clip);\n        actionIdle.setLoop(THREE.LoopRepeat, Infinity);\n      }\n      tryDone();\n    },\n    null,\n    err => { console.warn("idle.glb failed:", err); tryDone(); }\n  );\n\n  // Talking animation\n  loader.load("avatar/models/talking.glb",\n    gltf => {\n      if (gltf.animations.length > 0) {\n        const clip = fixClip(gltf.animations[0]);\n        actionTalking = mixer.clipAction(clip);\n        actionTalking.setLoop(THREE.LoopRepeat, Infinity);\n      }\n      tryDone();\n    },\n    null,\n    err => { console.warn("talking.glb failed:", err); tryDone(); }\n  );\n\n  // Nod animation\n  loader.load("avatar/models/nod.glb",\n    gltf => {\n      if (gltf.animations.length > 0) {\n        const clip = fixClip(gltf.animations[0]);\n        actionNod = mixer.clipAction(clip);\n        actionNod.setLoop(THREE.LoopOnce, 1);\n        actionNod.clampWhenFinished = true;\n      }\n      tryDone();\n    },\n    null,\n    err => { console.warn("nod.glb failed:", err); tryDone(); }\n  );\n}\n\n// ── Animation switching ───────────────────────────────────────────────────\nfunction crossFadeTo(newAction, duration = 0.4) {\n  if (!newAction || newAction === currentAction) return;\n  newAction.reset().play();\n  if (currentAction) currentAction.crossFadeTo(newAction, duration, true);\n  currentAction = newAction;\n}\n\nfunction switchToIdle()    { crossFadeTo(actionIdle, 0.5); }\nfunction switchToTalking() { crossFadeTo(actionTalking, 0.3); }\n\nfunction playNod() {\n  if (!actionNod) return;\n  actionNod.reset().play();\n  setTimeout(() => switchToIdle(), 1200);\n}\n\n// ── Lip sync via jaw bone + morph targets ─────────────────────────────────\nfunction setLipSync(amp) {\n  // Clamp and smooth\n  currentJaw += (amp - currentJaw) * 0.28;\n  const a = Math.max(0, Math.min(1, currentJaw));\n\n  // Option 1: jaw bone rotation (works on most Mixamo characters)\n  if (jawBone) {\n    jawBone.rotation.x = a * 0.3;  // rotates jaw open\n  }\n\n  // Option 2: morph targets (works if character has viseme shapes)\n  for (const mesh of morphMeshes) {\n    const d = mesh.morphTargetDictionary;\n    if (!d) continue;\n    const trySet = (name, val) => {\n      const idx = d[name];\n      if (idx !== undefined) mesh.morphTargetInfluences[idx] = val;\n    };\n    trySet("jawOpen",       a);\n    trySet("mouthOpen",     a);\n    trySet("viseme_aa",     a * 0.8);\n    trySet("viseme_O",      a * 0.4);\n  }\n}\n\n// ── Web Audio ─────────────────────────────────────────────────────────────\nlet audioCtx = null, analyser = null, freqData = null;\n\nfunction ensureAudio() {\n  if (audioCtx) return;\n  audioCtx = new (window.AudioContext || window.webkitAudioContext)();\n  analyser = audioCtx.createAnalyser();\n  analyser.fftSize = 256;\n  analyser.smoothingTimeConstant = 0.6;\n  freqData = new Uint8Array(analyser.frequencyBinCount);\n  analyser.connect(audioCtx.destination);\n}\n\nasync function playAudio(b64wav) {\n  ensureAudio();\n  if (audioCtx.state === "suspended") await audioCtx.resume();\n\n  const binary = atob(b64wav);\n  const bytes  = new Uint8Array(binary.length);\n  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);\n\n  const buffer = await audioCtx.decodeAudioData(bytes.buffer);\n  const src    = audioCtx.createBufferSource();\n  src.buffer   = buffer;\n  src.connect(analyser);\n  src.start();\n\n  isSpeaking = true;\n  switchToTalking();\n  setStatus("speaking");\n\n  src.onended = () => {\n    isSpeaking = false;\n    setLipSync(0);\n    switchToIdle();\n    setStatus("listening");\n  };\n}\n\n// ── Starfield ─────────────────────────────────────────────────────────────\nconst sc   = document.getElementById("stars");\nconst sx   = sc.getContext("2d");\nlet stars  = [];\n\nfunction initStars() {\n  sc.width = innerWidth; sc.height = innerHeight;\n  stars = Array.from({ length: 200 }, () => ({\n    x: Math.random() * sc.width,\n    y: Math.random() * sc.height,\n    r: Math.random() * 1.4 + 0.2,\n    a: Math.random(),\n    sp: Math.random() * 0.4 + 0.1,\n  }));\n}\ninitStars();\naddEventListener("resize", initStars);\n\nfunction drawStars(dt) {\n  sx.clearRect(0, 0, sc.width, sc.height);\n  for (const s of stars) {\n    s.a += s.sp * dt;\n    sx.beginPath();\n    sx.arc(s.x, s.y, s.r, 0, Math.PI * 2);\n    sx.fillStyle = `rgba(180,205,255,${0.2 + 0.28 * Math.sin(s.a)})`;\n    sx.fill();\n  }\n}\n\n// ── Main loop ─────────────────────────────────────────────────────────────\nlet T = 0;\nconst clock = { prev: performance.now() };\n\nfunction animate() {\n  requestAnimationFrame(animate);\n  const now = performance.now();\n  const dt  = Math.min((now - clock.prev) / 1000, 0.05);\n  clock.prev = now;\n  T += dt;\n\n  drawStars(dt);\n  controls.update();\n\n  if (mixer) mixer.update(dt);\n\n  // Pulse glow ring\n  ring.scale.setScalar(1 + Math.sin(T * 1.4) * 0.025);\n  ringM.opacity = 0.35 + Math.abs(Math.sin(T * 0.9)) * 0.2;\n\n  // Lip sync from live audio\n  if (analyser && isSpeaking) {\n    analyser.getByteFrequencyData(freqData);\n    let sum = 0;\n    for (let i = 2; i < 30; i++) sum += freqData[i];\n    setLipSync(Math.min(1, (sum / 28 / 255) * 2.8));\n  } else {\n    setLipSync(0);\n  }\n\n  renderer.render(scene, camera);\n}\nanimate();\n\n// ── WebSocket ─────────────────────────────────────────────────────────────\nfunction connectWS() {\n  const ws = new WebSocket(WS_URL);\n  ws.onopen  = () => setStatus("listening");\n  ws.onclose = () => { setStatus("disconnected"); setTimeout(connectWS, 2000); };\n  ws.onmessage = async e => {\n    const msg = JSON.parse(e.data);\n    switch (msg.type) {\n      case "status":\n        setStatus(msg.value);\n        if (msg.value === "thinking") playNod();\n        break;\n      case "transcript":\n        addMessage(msg.speaker, msg.text);\n        break;\n      case "speak":\n        if (msg.transcript) addMessage("assistant", msg.transcript);\n        await playAudio(msg.audio);\n        break;\n    }\n  };\n}\nconnectWS();\n\n// ── UI helpers ────────────────────────────────────────────────────────────\nfunction setStatus(s) {\n  document.getElementById("sdot").className = s;\n  const wave = document.getElementById("wave");\n  wave.className = s === "speaking" ? "active" : "";\n  const labels = {\n    listening:    "Listening — press Enter to speak",\n    recording:    "Recording — press Enter to stop",\n    thinking:     "Thinking...",\n    speaking:     "Speaking...",\n    disconnected: "Reconnecting...",\n  };\n  document.getElementById("stxt").textContent = labels[s] || s;\n}\n\nfunction addMessage(speaker, text) {\n  if (!text.trim()) return;\n  const div = document.getElementById("messages");\n  const el  = document.createElement("div");\n  el.className = `msg ${speaker}`;\n  el.innerHTML = `<span class="who">${speaker === "user" ? "You" : "Assistant"}</span><p>${text}</p>`;\n  div.appendChild(el);\n  div.scrollTop = div.scrollHeight;\n}\n</script>\n</body>\n</html>'
